// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant PK = 1;
    address maker;
    uint256 tokenId;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = vm.addr(PK);

        vm.warp(1);

        // build a long-call order so fillOrder mints a token owned by `maker`
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20s = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721s = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: address(this), // has code; premium is 0 so the low-level transferFrom succeeds
            strike: 0,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20s,
            erc721Assets: erc721s
        });

        bytes32 orderHash = c.hashOrder(order);
        tokenId = uint256(orderHash);

        (uint8 v, bytes32 r, bytes32 s) = vm.sign(PK, orderHash);
        bytes memory sig = abi.encodePacked(r, s, v);

        uint256[] memory floorIds = new uint256[](0);
        c.fillOrder(order, sig, floorIds);

        // sanity: maker owns the minted position token
        require(c.ownerOf(tokenId) == maker, "setup failed");
    }

    function testFuzz_property(address to) public {
        vm.assume(to != address(0));
        vm.assume(to != maker);

        vm.prank(maker);
        c.transferFrom(maker, to, tokenId);

        assertTrue(c.ownerOf(tokenId) == to);
    }
}

