pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    SigMaker maker;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = new SigMaker();
    }

    function testFuzz_property(uint256 nonce, uint256 duration, address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(this) && recipient != address(c));
        duration = bound(duration, 0, 9_999 days);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(c),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory emptyIds = new uint256[](0);
        uint256 positionId = c.fillOrder(order, "", emptyIds);

        // first transfer of our position token by its owner (this test contract)
        c.transferFrom(address(this), recipient, positionId);

        // general rule: after a successful transfer, the previous owner can no longer transfer it
        bool ok;
        try c.transferFrom(address(this), recipient, positionId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

