pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Test contract acts as maker (ERC1271 signer) and as baseAsset ERC20 stub.
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }

    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        return true;
    }

    function setUp() public {
        c = new C("", 0, address(this));
    }

    function testFuzz_property(uint256 premium, address to, address spender) public {
        vm.assume(to != address(0));
        vm.assume(to != address(this));
        vm.assume(to != address(c));
        premium = bound(premium, 0, 1e30);

        C.Order memory order;
        order.maker = address(this);
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(this);
        order.strike = 1;
        order.premium = premium;
        order.duration = 1 days;
        order.expiration = block.timestamp + 1 hours;
        order.nonce = 0;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        bytes32 orderHash = c.hashOrder(order);
        uint256 id = uint256(orderHash);

        // Maker (this contract, ERC1271) signs; mint happens: id is owned by maker.
        c.fillOrder(order, new bytes(0), new uint256[](0));

        // Maker transfers the token away to `to`.
        c.transferFrom(address(this), to, id);

        // RULE: after transferring an NFT away, the previous owner can no longer
        // approve a spender for it (approve requires msg.sender == _ownerOf[id]).
        bool ok = true;
        try c.approve(spender, id) {
            ok = false;
        } catch {
            ok = true;
        }
        assertTrue(ok);
    }
}

