        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: address(this),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerKey, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        vm.prank(filler1);
        c.fillOrder(order, signature, floorAssetTokenIds);

        uint256 oppositeId = uint256(c.hashOppositeOrder(order));

        vm.prank(filler2);
        c.fillOrder(order, signature, floorAssetTokenIds);

        assertEq(c.ownerOf(oppositeId), filler1);
    }
}

