    fallback() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    uint256 constant MAKER_PK = 0xA11CE;
    address maker;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = vm.addr(MAKER_PK);
    }

    function testFuzz_property(uint256 strike, uint256 premium, uint256 duration, address recipient, uint256 warpTime) public {
        // keep params in the admissible domain (wide)
        vm.assume(recipient != address(0) && recipient != maker);
        strike = bound(strike, 0, 1e30);
        premium = bound(premium, 0, 1e30);
        duration = bound(duration, 1 days, 9_000 days);
        warpTime = bound(warpTime, 1, 1_000_000);

        vm.warp(warpTime);

        // build a valid, signable order so a position token gets minted to maker
        C.Order memory order;
        order.maker = maker;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(c); // c has code, satisfies baseAsset check; premium/strike are 0-ish paths
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = block.timestamp + 10_000 days;
        order.nonce = 0;

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(MAKER_PK, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        uint256[] memory noFloor = new uint256[](0);

        vm.prank(maker);
        c.fillOrder(order, signature, noFloor);

        uint256 tokenId = uint256(orderHash);
        vm.assume(c.ownerOf(tokenId) == maker); // token minted to maker

        // drive the mutated unit: c.transferFrom, as a SELF-transfer by the owner
        uint256 balBefore = c.balanceOf(maker);

        vm.prank(maker);
        c.transferFrom(maker, maker, tokenId);

        // General rule: a transferFrom of a token to its current owner (self-transfer)
        // must not change the owner's token balance — the sender's balance is debited
        // exactly as the recipient's is credited.
        assertTrue(c.balanceOf(maker) == balBefore, "self-transfer must not change owner balance");
    }
}

