pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MockERC20 token;
    ERC1271Signer signer;

    function setUp() public {
        c = new C("", 0, address(this));
        token = new MockERC20();
        signer = new ERC1271Signer();
    }

    function testFuzz_property(uint256 strike, uint256 duration, uint256 nonce) public {
        vm.assume(strike < 2 ** 128);
        duration = bound(duration, 1, 9999 days);

        C.Order memory order;
        order.maker = address(signer);
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(token);
        order.strike = strike;
        order.premium = 0;
        order.duration = duration;
        order.expiration = block.timestamp + 1;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        uint256[] memory noFloorIds = new uint256[](0);

        // Fill the order: mints the long position token to this test contract.
        c.fillOrder(order, "", noFloorIds);

        uint256 positionId = uint256(c.hashOppositeOrder(order));

        uint256 balBefore = c.balanceOf(address(this));

        // Self-transfer of the owned token must conserve the owner's balance.
        c.transferFrom(address(this), address(this), positionId);

        assertTrue(balBefore == c.balanceOf(address(this)));
    }
}

contract ERC1271Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        return true;
    }
}
